 1	/**
 2	 * Tests for src/gui/queue/get-queue.ts — WP-005
 3	 *
 4	 * Verifies:
 5	 *   AC-1: getQueue() returns entries with projectExists: true when the
 6	 *         project ledger file exists on disk.
 7	 *   AC-2: getQueue() returns entries with projectExists: false when no
 8	 *         project ledger file exists for the entry's expectedSlug.
 9	 */
10	
11	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
12	import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
13	import { join } from 'node:path';
14	import { tmpdir } from 'node:os';
15	
16	import { getQueue } from '../../../src/gui/queue/get-queue.js';
17	import { QUEUE_FILENAME } from '../../../src/gui/queue/types.js';
18	
19	// ---------------------------------------------------------------------------
20	// Helpers
21	// ---------------------------------------------------------------------------
22	
23	interface TestEnv {
24	  tempDir: string;
25	  logsDir: string;
26	  ledgerRoot: string;
27	}
28	
29	async function setup(): Promise<TestEnv> {
30	  const tempDir    = await mkdtemp(join(tmpdir(), 'get-queue-test-'));
31	  const logsDir    = join(tempDir, 'logs');
32	  const ledgerRoot = join(tempDir, 'ledger');
33	  await mkdir(logsDir,    { recursive: true });
34	  await mkdir(ledgerRoot, { recursive: true });
35	  return { tempDir, logsDir, ledgerRoot };
36	}
37	
38	async function teardown(tempDir: string): Promise<void> {
39	  await rm(tempDir, { recursive: true, force: true });
40	}
41	
42	/**
43	 * Writes a minimal `.run-queue.json` with a single entry whose PID is
44	 * intentionally unreachable. Avoid PID 0 — `process.kill(0, 0)` targets the
45	 * current process group on POSIX systems. Use a very large integer that is
46	 * almost certainly unused instead.
47	 */
48	async function writeQueue(logsDir: string, slug: string, pid = 999_999_999): Promise<void> {
49	  const entry = {
50	    id:          'test-id-1',
51	    pid,
52	    planPath:    `/fake/plans/${slug}`,
53	    expectedSlug: slug,
54	    startedAt:   '2026-05-20T00:00:00Z',
55	    status:      'pending',
56	  };
57	  await writeFile(join(logsDir, QUEUE_FILENAME), JSON.stringify([entry]), 'utf-8');
58	}
59	
60	/**
61	 * Creates a minimal project-ledger.json at `<ledgerRoot>/<slug>/project-ledger.json`.
62	 */
63	async function createProjectLedger(ledgerRoot: string, slug: string): Promise<void> {
64	  const projectDir = join(ledgerRoot, slug);
65	  await mkdir(projectDir, { recursive: true });
66	  await writeFile(
67	    join(projectDir, 'project-ledger.json'),
68	    JSON.stringify({ synthesis_generated: false }),
69	    'utf-8',
70	  );
71	}
72	
73	// ---------------------------------------------------------------------------
74	// AC-1: projectExists is true when the ledger file exists
75	// ---------------------------------------------------------------------------
76	
77	describe('getQueue — AC-1: projectExists is true when ledger file exists', () => {
78	  let env: TestEnv;
79	
80	  beforeEach(async () => {
81	    env = await setup();
82	  });
83	
84	  afterEach(async () => {
85	    await teardown(env.tempDir);
86	  });
87	
88	  it('returns projectExists: true for an entry whose project ledger exists', async () => {
89	    const slug = '2026-05-20-my-feature';
90	    await writeQueue(env.logsDir, slug);
91	    await createProjectLedger(env.ledgerRoot, slug);
92	
93	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
94	
95	    expect(entries).toHaveLength(1);
96	    expect(entries[0].projectExists).toBe(true);
97	    expect(entries[0].expectedSlug).toBe(slug);
98	  });
99	});

 1	/**
 2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
 3	 *
 4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
 5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
 6	 *
 7	 * This module is read-only with respect to the queue file and all other files.
 8	 *
 9	 * Exports beyond `getQueue()`:
10	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
11	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
12	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
13	 *     in `orchestrator-manager.ts`.
14	 */
15	
16	import { readFile } from 'node:fs/promises';
17	import { join } from 'node:path';
18	
19	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
20	import { resolveProgress } from './resolve-progress.js';
21	import { computeEffectiveStatus } from './compute-effective-status.js';
22	
23	// ---------------------------------------------------------------------------
24	// PID alive check
25	// ---------------------------------------------------------------------------
26	
27	/**
28	 * Returns `true` if the process with `pid` exists on this machine.
29	 *
30	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
31	 * verifies the process exists and does not actually deliver any signal.
32	 *
33	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
34	 */
35	export function isProcessAlive(pid: number): boolean {
36	  try {
37	    process.kill(pid, 0);
38	    return true;
39	  } catch {
40	    return false;
41	  }
42	}
43	
44	// ---------------------------------------------------------------------------
45	// Queue file reader
46	// ---------------------------------------------------------------------------
47	
48	/**
49	 * Reads and parses `<logsDir>/.run-queue.json`.
50	 * Returns `[]` on any I/O or parse error — fail-safe.
51	 * Never writes to the queue file.
52	 *
53	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
54	 */
55	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
56	  const queuePath = join(logsDir, QUEUE_FILENAME);
57	  let raw: string;
58	  try {
59	    raw = await readFile(queuePath, 'utf-8');
60	  } catch {
61	    return [];
62	  }
63	  try {
64	    const data: unknown = JSON.parse(raw);
65	    if (!Array.isArray(data)) return [];
66	    return data.filter(isRawQueueEntry);
67	  } catch {
68	    return [];
69	  }
70	}
71	
72	/**
73	 * Type-guard that validates a raw JSON value as a `RawQueueEntry`.
74	 *
75	 * Returns `true` only when **all five** of the following rules pass:
76	 *
77	 * 1. **Type check** — `entry` is a non-null object.
78	 * 2. **String fields** — `id`, `planPath`, and `startedAt` are strings.
79	 * 3. **PID integer** — `pid` is a finite integer (rejects floats).
80	 * 4. **PID positive** — `pid` is greater than zero (rejects zero and negatives).
81	 * 5. **Non-empty slug** — `expectedSlug` is a non-empty, non-whitespace-only string
82	 *    (rejects missing, empty-string, and whitespace-only slugs).
83	 *
84	 * Used internally by `readQueueFile` to filter the parsed JSON array before
85	 * it is returned as `RawQueueEntry[]`.
86	 *
87	 * @returns `true` when every rule passes; `false` otherwise.
88	 */
89	function isRawQueueEntry(entry: unknown): entry is RawQueueEntry {
90	  if (typeof entry !== 'object' || entry === null) return false;
91	  const e = entry as Record<string, unknown>;
92	  return (
93	    typeof e['id'] === 'string' &&
94	    typeof e['pid'] === 'number' && Number.isInteger(e['pid']) && (e['pid'] as number) > 0 &&
95	    typeof e['planPath'] === 'string' &&
96	    typeof e['expectedSlug'] === 'string' && (e['expectedSlug'] as string).trim().length > 0 &&
97	    typeof e['startedAt'] === 'string'
98	  );
99	}

100	
101	// ---------------------------------------------------------------------------
102	// AC-2: projectExists is false when the ledger file does not exist
103	// ---------------------------------------------------------------------------
104	
105	describe('getQueue — AC-2: projectExists is false when ledger file is absent', () => {
106	  let env: TestEnv;
107	
108	  beforeEach(async () => {
109	    env = await setup();
110	  });
111	
112	  afterEach(async () => {
113	    await teardown(env.tempDir);
114	  });
115	
116	  it('returns projectExists: false for an entry with no project ledger on disk', async () => {
117	    const slug = '2026-05-20-no-ledger';
118	    await writeQueue(env.logsDir, slug);
119	    // Intentionally do NOT create a project ledger for this slug.
120	
121	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
122	
123	    expect(entries).toHaveLength(1);
124	    expect(entries[0].projectExists).toBe(false);
125	    expect(entries[0].expectedSlug).toBe(slug);
126	  });
127	});
128	
129	// ---------------------------------------------------------------------------
130	// AC-3 (rework): isRawQueueEntry rejects entries with empty-string expectedSlug
131	// ---------------------------------------------------------------------------
132	
133	describe('getQueue — validator: rejects entry with empty expectedSlug', () => {
134	  let env: TestEnv;
135	
136	  beforeEach(async () => {
137	    env = await setup();
138	  });
139	
140	  afterEach(async () => {
141	    await teardown(env.tempDir);
142	  });
143	
144	  it('filters out an entry whose expectedSlug is an empty string', async () => {
145	    // Write a queue with one entry that has an empty expectedSlug.
146	    const invalidEntry = {
147	      id:           'test-empty-slug',
148	      pid:          999_999_999,
149	      planPath:     '/fake/plans/empty-slug',
150	      expectedSlug: '',
151	      startedAt:    '2026-05-20T00:00:00Z',
152	      status:       'pending',
153	    };
154	    await writeFile(
155	      join(env.logsDir, QUEUE_FILENAME),
156	      JSON.stringify([invalidEntry]),
157	      'utf-8',
158	    );
159	
160	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
161	
162	    expect(entries).toHaveLength(0);
163	  });
164	
165	  it('filters out an entry whose expectedSlug is whitespace-only', async () => {
166	    // Write a queue with one entry that has a whitespace-only expectedSlug.
167	    const invalidEntry = {
168	      id:           'test-whitespace-slug',
169	      pid:          999_999_999,
170	      planPath:     '/fake/plans/whitespace-slug',
171	      expectedSlug: '   ',
172	      startedAt:    '2026-05-20T00:00:00Z',
173	      status:       'pending',
174	    };
175	    await writeFile(
176	      join(env.logsDir, QUEUE_FILENAME),
177	      JSON.stringify([invalidEntry]),
178	      'utf-8',
179	    );
180	
181	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
182	
183	    expect(entries).toHaveLength(0);
184	  });
185	});

